def count_primes(n):
    primes = []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(n**0.5) + 1):
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)
    return len(primes)

n = 36
pi_n = count_primes(n)
print(f"pi({n}) = {pi_n}")

# Check the boundary condition derived from the problem: 2^omega(K) <= 4000
# If n >= 34, omega(K) = pi(n).
max_n_check = 37
pi_max_n = count_primes(max_n_check - 1) # pi(36)
print(f"2^pi({36}) = {2**pi_max_n}")

pi_too_large_n = count_primes(max_n_check) # pi(37)
print(f"2^pi({37}) = {2**pi_too_large_n}")
